package com.personal.assistant.module.backup.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.backup.dto.BackupVerificationResponse;import com.personal.assistant.module.backup.entity.BackupRecord;import com.personal.assistant.module.backup.mapper.BackupRecordMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
@Service public class BackupService{private static final String NOTICE="备份文件校验通过不等同于恢复成功，正式环境仍需定期执行真实恢复演练。";private final BackupRecordMapper records;private final AtomicBoolean running=new AtomicBoolean();@Value("${app.backup.script:/app/scripts/backup.sh}")private String script;@Value("${app.backup.directory:/app/backup}")private String directory;@Value("${app.backup.retention-days:14}")private int retentionDays;public BackupService(BackupRecordMapper r){records=r;}public List<BackupRecord>list(Long uid){return records.selectList(new LambdaQueryWrapper<BackupRecord>().eq(BackupRecord::getUserId,uid).orderByDesc(BackupRecord::getStartedAt).last("limit 100"));}public BackupRecord runFullBackup(){return runFullBackup(null);}public BackupRecord runFullBackup(Long uid){if(!running.compareAndSet(false,true))throw new BusinessException(ErrorCode.BUSINESS_ERROR,"已有备份任务正在运行");BackupRecord r=new BackupRecord();r.setUserId(uid);r.setBackupType("FULL");r.setStatus("RUNNING");r.setVerificationStatus("NOT_VERIFIED");r.setStartedAt(now());records.insert(r);try{Path path=Path.of(script);if(!Files.exists(path))throw new IllegalStateException("备份脚本不存在: "+script);ProcessBuilder pb=new ProcessBuilder("sh",script);pb.redirectErrorStream(true);pb.environment().put("BACKUP_DIR",directory);pb.environment().put("RETENTION_DAYS",String.valueOf(retentionDays));Process p=pb.start();String output=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(!p.waitFor(10,TimeUnit.MINUTES)){p.destroyForcibly();throw new IllegalStateException("备份执行超时");}if(p.exitValue()!=0)throw new IllegalStateException("备份失败: "+output.trim());String file=Arrays.stream(output.split("\\R")).filter(x->x.startsWith("BACKUP_FILE=")).map(x->x.substring(12)).findFirst().orElse(null);r.setFilePath(file);if(file!=null&&Files.isRegularFile(Path.of(file))){r.setFileSize(Files.size(Path.of(file)));r.setSha256(sha256(Path.of(file)));}r.setStatus("SUCCESS");r.setMessage(output.trim());return r;}catch(Exception e){r.setStatus("FAILED");r.setMessage(e.getMessage());throw new BusinessException(ErrorCode.BUSINESS_ERROR,e.getMessage());}finally{r.setFinishedAt(now());records.updateById(r);running.set(false);}}
 public BackupVerificationResponse verify(Long uid,Long id){BackupRecord r=records.selectById(id);if(r==null||!uid.equals(r.getUserId()))throw new BusinessException(ErrorCode.NOT_FOUND,"备份记录不存在");String status="FAILED",message;Long size=null;String digest=null;try{if(r.getFilePath()==null)throw new IOException("备份记录没有文件路径");Path path=Path.of(r.getFilePath());if(!Files.isRegularFile(path))throw new IOException("备份文件不存在或不是普通文件");size=Files.size(path);if(r.getFileSize()!=null&&!r.getFileSize().equals(size))throw new IOException("文件大小不一致，记录="+r.getFileSize()+"，实际="+size);digest=sha256(path);if(r.getSha256()!=null&&!r.getSha256().equalsIgnoreCase(digest))throw new IOException("SHA-256 摘要不一致");if(r.getSha256()==null)r.setSha256(digest);status="VERIFIED";message="文件存在、大小与 SHA-256 摘要校验通过";}catch(Exception e){message=e.getMessage();}r.setVerificationStatus(status);r.setVerifiedAt(now());r.setVerificationMessage(message);records.updateById(r);return new BackupVerificationResponse(id,status,digest,size,r.getVerifiedAt(),message,NOTICE);}private String sha256(Path path)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(path)){byte[]buf=new byte[8192];for(int n;(n=in.read(buf))>0;)md.update(buf,0,n);}return HexFormat.of().formatHex(md.digest());}private LocalDateTime now(){return LocalDateTime.now(ZoneId.of("Asia/Shanghai"));}}
